import (
	"strconv"
	"testing"
)

func TestCountNoAdjacentEqualExamples(t *testing.T) {
	cases := map[string]int{
		"1": 1, "9": 9, "10": 10, "11": 10, "12": 11, "100": 90, "101": 91,
	}
	for n, want := range cases {
		if got := countNoAdjacentEqual(n); got != want {
			t.Fatalf("countNoAdjacentEqual(%q) = %d, want %d", n, got, want)
		}
	}
}

// TestCountNoAdjacentEqualAgainstBruteForce walks every n up to 200000 and
// keeps a running count, so the drill is checked at every bound rather than at
// a handful of them. Enumerating like this is exactly what the 10^18 tests
// below rule out.
func TestCountNoAdjacentEqualAgainstBruteForce(t *testing.T) {
	running := 0
	for v := 1; v <= 200000; v++ {
		s := strconv.Itoa(v)
		ok := true
		for i := 1; i < len(s); i++ {
			if s[i] == s[i-1] {
				ok = false
				break
			}
		}
		if ok {
			running++
		}
		if got := countNoAdjacentEqual(s); got != running {
			t.Fatalf("countNoAdjacentEqual(%q) = %d, want %d", s, got, running)
		}
	}
}

// TestCountNoAdjacentEqualAtNines pins the two bounds whose answer is a closed
// form: every d-digit string with no repeat is reachable below 10^18, and
// 10^18 itself has adjacent zeros so it adds nothing.
func TestCountNoAdjacentEqualAtNines(t *testing.T) {
	want, p := 0, 1
	for d := 1; d <= 18; d++ {
		p *= 9
		want += p
	}
	if got := countNoAdjacentEqual("999999999999999999"); got != want {
		t.Fatalf("18 nines = %d, want %d", got, want)
	}
	if got := countNoAdjacentEqual("1000000000000000000"); got != want {
		t.Fatalf("10^18 = %d, want %d", got, want)
	}
}

// TestCountNoAdjacentEqualAtRoundNumbers uses bounds of the form d000...0 with
// at least two zeros. The bound's own prefix dies at its second zero, so the
// answer is everything shorter plus (d-1) free completions, with no
// contribution from the bound itself.
func TestCountNoAdjacentEqualAtRoundNumbers(t *testing.T) {
	for k := 2; k <= 18; k++ {
		for d := 1; d <= 9; d++ {
			s := strconv.Itoa(d)
			for i := 0; i < k; i++ {
				s += "0"
			}
			want, p := 0, 1
			for j := 1; j <= k; j++ {
				p *= 9
				want += p
			}
			want += (d - 1) * p
			if got := countNoAdjacentEqual(s); got != want {
				t.Fatalf("countNoAdjacentEqual(%q) = %d, want %d", s, got, want)
			}
		}
	}
}

