// firstPlayerWins reports whether the player to move wins the subtraction game
// under optimal play from both sides.
func firstPlayerWins(piles []int, moves []int) bool {
	largest := 0
	for _, p := range piles {
		if p > largest {
			largest = p
		}
	}
	// grundy[n] is the value of a single pile of n stones: the smallest
	// non-negative number not reachable in one move. It is at most len(moves).
	grundy := make([]int, largest+1)
	// seen[v] == n means value v was reachable from n, which avoids clearing
	// the scratch array on every iteration.
	seen := make([]int, len(moves)+1)
	for i := range seen {
		seen[i] = -1
	}
	for n := 1; n <= largest; n++ {
		for _, m := range moves {
			if m <= n {
				seen[grundy[n-m]] = n
			}
		}
		mex := 0
		for seen[mex] == n {
			mex++
		}
		grundy[n] = mex
	}

	// The game is the sum of independent piles, so its value is the xor of
	// theirs, and a value of zero is exactly a loss for the player to move.
	x := 0
	for _, p := range piles {
		x ^= grundy[p]
	}
	return x != 0
}

