import (
	"math/rand"
	"testing"
)

// bruteCount enumerates all 2^n subsets. At n = 40 that is a trillion of them,
// which is the whole point of the large tests below.
func bruteCount(nums []int, target int) int {
	c := 0
	for mask := 0; mask < 1<<len(nums); mask++ {
		s := 0
		for i, v := range nums {
			if mask&(1<<i) != 0 {
				s += v
			}
		}
		if s <= target {
			c++
		}
	}
	return c
}

func TestCountSubsetsAtMostSmallCases(t *testing.T) {
	if got := countSubsetsAtMost(nil, 0); got != 1 {
		t.Fatalf("no numbers: got %d, want 1 (the empty subset)", got)
	}
	if got := countSubsetsAtMost([]int{5}, 4); got != 1 {
		t.Fatalf("one number above the target: got %d, want 1", got)
	}
	if got := countSubsetsAtMost([]int{5}, -1); got != 0 {
		t.Fatalf("negative target: got %d, want 0", got)
	}
	if got := countSubsetsAtMost([]int{1, 2, 3}, 3); got != 5 {
		t.Fatalf("{1,2,3} at most 3: got %d, want 5", got)
	}
}

func TestCountSubsetsAtMostAgainstBruteForce(t *testing.T) {
	rng := rand.New(rand.NewSource(20260907))
	for trial := 0; trial < 200; trial++ {
		nums := make([]int, rng.Intn(15))
		total := 0
		for i := range nums {
			nums[i] = rng.Intn(60)
			total += nums[i]
		}
		target := rng.Intn(total + 2)
		if got, want := countSubsetsAtMost(nums, target), bruteCount(nums, target); got != want {
			t.Fatalf("nums=%v target=%d: got %d, want %d", nums, target, got, want)
		}
	}
}

// TestCountSubsetsAtMostOnPowersOfTwo uses 40 distinct powers of two, whose
// subset sums are exactly the integers 0..2^40-1, so the answer for target t is
// t+1 with no reference implementation needed.
func TestCountSubsetsAtMostOnPowersOfTwo(t *testing.T) {
	nums := make([]int, 40)
	for i := range nums {
		nums[i] = 1 << i
	}
	for _, target := range []int{0, 1, 1023, 123456789012, 1<<40 - 1} {
		if got := countSubsetsAtMost(nums, target); got != target+1 {
			t.Fatalf("powers of two at most %d: got %d, want %d", target, got, target+1)
		}
	}
}

// TestCountSubsetsAtMostOnLargeValues checks 40 values around 10^12, where no
// table indexed by the sum could ever be allocated. The oracle is complementing
// each subset: sum > target on one side is sum <= total-target-1 on the other,
// so the two counts must add up to 2^40.
func TestCountSubsetsAtMostOnLargeValues(t *testing.T) {
	rng := rand.New(rand.NewSource(577))
	nums := make([]int, 40)
	total := 0
	for i := range nums {
		nums[i] = 1 + rng.Intn(1000000000000)
		total += nums[i]
	}
	for _, target := range []int{total / 3, total / 2, total - 1} {
		lo := countSubsetsAtMost(nums, target)
		hi := countSubsetsAtMost(nums, total-target-1)
		if lo+hi != 1<<40 {
			t.Fatalf("target %d: %d + %d = %d, want %d", target, lo, hi, lo+hi, 1<<40)
		}
	}
	if got := countSubsetsAtMost(nums, total); got != 1<<40 {
		t.Fatalf("target equal to the total: got %d, want %d", got, 1<<40)
	}
}

// TestCountSubsetsAtMostWithRepeats makes every value identical, so the answer
// counts subsets by size and is a partial sum of binomial coefficients. Many
// equal sums is where a strict-versus-non-strict comparison goes wrong.
func TestCountSubsetsAtMostWithRepeats(t *testing.T) {
	const n, v = 40, 1000000007
	nums := make([]int, n)
	for i := range nums {
		nums[i] = v
	}
	binom := make([]int, n+1)
	binom[0] = 1
	for k := 1; k <= n; k++ {
		binom[k] = binom[k-1] * (n - k + 1) / k
	}
	for _, k := range []int{0, 1, 20, 39, 40} {
		want := 0
		for j := 0; j <= k; j++ {
			want += binom[j]
		}
		if got := countSubsetsAtMost(nums, k*v); got != want {
			t.Fatalf("%d copies allowed: got %d, want %d", k, got, want)
		}
		if got := countSubsetsAtMost(nums, k*v+v-1); got != want {
			t.Fatalf("just below the next size: got %d, want %d", got, want)
		}
	}
}

